('vocab_threaten','threaten','verb','to put someone or something at risk of harm or loss','[{"senseId":"threaten_1","meaning":"to put someone or something at risk of harm or loss","acceptedParaphrases":["put at risk","endanger"],"masteryContexts":[{"contextId":"u1_11_threaten_meaning","text":"A serious knee injury could threaten her place in the national squad.","meaning":"put something precious in real danger","wrongMeanings":["make a plan to protect something valuable","help something to improve slowly","remove something from a list early"]},{"contextId":"u1_11_threaten_paraphrase","text":"Poor funding may threaten the future of the community football club.","meaning":"make harm or loss more likely","wrongMeanings":["make a decision more difficult to explain","bring new members to a group","lead to a change in plans"]}],"situationDistractors":["Our new coach helped to protect her place in the team.","A long holiday gave her injury time to heal.","Her place in the team was announced early in the week.","A generous sponsor promised to support the club for another year."],"gapDistractors":[{"contextId":"u1_11_threaten_gap_base_noun","answer":"threaten","wrong":["protect","strengthen","advance"]},{"contextId":"u1_11_threaten_gap_third_noun","answer":"threatens","wrong":["strengthens","protects","improves"]},{"contextId":"u1_11_threaten_gap_past_noun","answer":"threatened","wrong":["strengthened","protected","improved"]},{"contextId":"u1_11_threaten_gap_perfect_noun","answer":"threatened","wrong":["protected","secured","strengthened"]},{"contextId":"u1_11_threaten_gap_past_inf","answer":"threatened","wrong":["suggested","explained","volunteered"]},{"contextId":"u1_11_threaten_gap_third_inf","answer":"threatens","wrong":["suggests","explains","announces"]}],"spellingErrors":["threten","thretan","threatan","thretten","threaton","theaten"],"wordFamilyForms":[{"form":"threaten","partOfSpeech":"verb","example":"Rising costs may threaten the future of small clubs.","pedagogicallyUseful":true},{"form":"threat","partOfSpeech":"noun","example":"Heavy rain is a real threat to the outdoor final.","pedagogicallyUseful":true,"altExample":"Heavy snow was a serious threat to the success of the school sports day."},{"form":"threatening","partOfSpeech":"adjective","example":"The sky looked dark and threatening before the match.","pedagogicallyUseful":true,"altExample":"The dark clouds looked threatening, so the match was moved indoors."}],"masteryPassages":[{"passageId":"u1_11_threaten_passage_1","contextId":"u1_11_threaten_gap_base_noun","text":"Scientists warn that sea levels are rising faster than expected. This could ____ many coastal towns within fifty years.","answer":"threaten"},{"passageId":"u1_11_threaten_passage_2","contextId":"u1_11_threaten_gap_third_noun","text":"The striker limped off after a late tackle. It ____ to end his season, but the scan showed no serious damage and he was back in training within days.","answer":"threatened"}],"contextDependentParaphrases":[],"wrongParaphrases":["keep safe","give help to","make easier for"],"misleadingDistractors":["protect","support","improve"],"grammarForms":{"base":"threaten","thirdPerson":"threatens","past":"threatened","pastParticiple":"threatened","ing":"threatening"},"grammarPatterns":["threaten + noun","threaten + to-infinitive"]}]'::jsonb,'["threat","threatening"]'::jsonb,'[]'::jsonb,'live'),
('vocab_resent','resent','verb','to feel angry or upset about something you think is unfair','[{"senseId":"resent_1","meaning":"to feel angry or upset about something you think is unfair","acceptedParaphrases":["feel bitter about","feel angry about"],"masteryContexts":[{"contextId":"u1_12_resent_meaning","text":"He began to resent being left out of the team, even though he had trained hard all season.","meaning":"feel bitter about unfair treatment","wrongMeanings":["feel proud of a team achievement","feel nervous before an important event","feel sorry for someone who is hurt"]},{"contextId":"u1_12_resent_paraphrase","text":"Many workers resent being told to stay late without extra pay.","meaning":"remain angry about perceived unfairness","wrongMeanings":["agree happily to accept a request","feel exhausted after an extremely busy day","feel surprised by a sudden change"]}],"situationDistractors":["He felt proud when he was chosen to captain the team.","She was delighted that her friend won the prize.","He felt nervous before his first race.","The player was sorry that he had shouted at the referee.","Her teammates were thrilled that she had been chosen for the national finals.","Delighted that his younger brother had joined the team, he told everybody proudly.","Her teammates encouraged her warmly and invited her to every social event."],"gapDistractors":[{"contextId":"u1_12_resent_gap_base_noun","answer":"resent","wrong":["appreciate","praise","welcome"]},{"contextId":"u1_12_resent_gap_third_ing","answer":"resents","wrong":["hopes","plans","appreciates"]},{"contextId":"u1_12_resent_gap_past_ing","answer":"resented","wrong":["hoped","planned","appreciated"]},{"contextId":"u1_12_resent_gap_past_object_ing","answer":"resented","wrong":["hoped","planned","appreciated"]},{"contextId":"u1_12_resent_gap_perfect_noun","answer":"resented","wrong":["inspected","photographed","repaired"]}],"spellingErrors":["resant","resint","resnet","ressent","resentt","resentd"],"wordFamilyForms":[{"form":"resent","partOfSpeech":"verb","example":"Some players resent being asked to train on Sundays.","pedagogicallyUseful":true},{"form":"resentment","partOfSpeech":"noun","example":"His resentment grew when he was dropped from the team again.","pedagogicallyUseful":true,"altExample":"His resentment grew whenever others were chosen to play instead of him."},{"form":"resentful","partOfSpeech":"adjective","example":"She felt resentful that her friends were allowed to leave early.","pedagogicallyUseful":true,"altExample":"She felt resentful after the referee ignored the unfair tackle."}],"masteryPassages":[{"passageId":"u1_12_resent_passage_1","contextId":"u1_12_resent_gap_base_noun","text":"Jack worked on the group project for three weeks. He began to ____ the others when they took the credit without doing any of the work.","answer":"resent"},{"passageId":"u1_12_resent_passage_2","contextId":"u1_12_resent_gap_third_ing","text":"Her brother always got the best seat in the car. She ____ it, though she never said so aloud.","answer":"resented"}],"contextDependentParaphrases":[],"wrongParaphrases":["feel proud of","feel nervous about","feel sorry for"],"misleadingDistractors":["celebrate","recommend","permit"],"grammarForms":{"base":"resent","thirdPerson":"resents","past":"resented","pastParticiple":"resented","ing":"resenting"},"grammarPatterns":["resent + noun","resent + -ing","resent + object + -ing"]}]'::jsonb,'["resentment","resentful"]'::jsonb,'[]'::jsonb,'live'),
('vocab_regret','regret','verb','to feel sorry about something that happened or something you did','[{"senseId":"regret_1","meaning":"to feel sorry about something that happened or something you did","acceptedParaphrases":["feel sorry about","wish had been different"],"masteryContexts":[{"contextId":"u1_13_regret_meaning","text":"He told me that he will always regret his own decision to leave school so early and often wishes he had stayed.","meaning":"feel sorry about a past choice","wrongMeanings":["feel proud of a decision made recently","feel unsure about a choice to be made","feel angry at someone else’s mistake"]},{"contextId":"u1_13_regret_paraphrase","text":"Looking back, she began to regret turning down the invitation to join the squad.","meaning":"wish an earlier choice had been different","wrongMeanings":["feel excited about an opportunity next year","explain why an invitation was refused","feel grateful to a person who helped"]}],"situationDistractors":["He felt angry that the coach picked another player.","She was happy about the choice she made.","He felt nervous about the choice he had to make.","She told everyone proudly that she had chosen to retire.","She felt delighted about her decision to join a much bigger club.","He was proud of the brave choice he made, and he never looked back at his old team.","She smiled happily when the long journey to the tournament was finally over.","Visitors to the museum admired the old trophies in the glass cabinets."],"gapDistractors":[{"contextId":"u1_13_regret_gap_base_ing","answer":"regret","wrong":["hope","plan","want"]},{"contextId":"u1_13_regret_gap_third_ing","answer":"regrets","wrong":["hopes","plans","wants"]},{"contextId":"u1_13_regret_gap_past_ing","answer":"regretted","wrong":["hoped","planned","wanted"]},{"contextId":"u1_13_regret_gap_perfect_that","answer":"regretted","wrong":["photographed","inspected","repaired"]},{"contextId":"u1_13_regret_gap_past_that","answer":"regretted","wrong":["photographed","inspected","repaired"]}],"spellingErrors":["regrett","regert","regrat","regreat","reggret","rigret"],"wordFamilyForms":[{"form":"regret","partOfSpeech":"verb","example":"You will regret skipping the warm-up if you pull a muscle.","pedagogicallyUseful":true},{"form":"regrettable","partOfSpeech":"adjective","example":"It is regrettable that so many fans missed the first goal.","pedagogicallyUseful":true,"altExample":"The injury was regrettable, but the team still played with great spirit."},{"form":"regrettably","partOfSpeech":"adverb","example":"The match, regrettably, has been cancelled.","pedagogicallyUseful":true,"altExample":"The swimming gala was regrettably cancelled because of the broken heating."}],"masteryPassages":[{"passageId":"u1_13_regret_passage_1","contextId":"u1_13_regret_gap_base_ing","text":"He left the exam hall early without checking his answers. Later, he began to ____ that decision, because he lost marks on careless mistakes.","answer":"regret"},{"passageId":"u1_13_regret_passage_2","contextId":"u1_13_regret_gap_third_ing","text":"Our team lost by six goals. Watching the final whistle, the coach was already ____ his decision to rest the best players.","answer":"regretting"}],"contextDependentParaphrases":[],"wrongParaphrases":["feel proud of","feel surprised by","feel certain about"],"misleadingDistractors":["celebrate","demand","deny"],"grammarForms":{"base":"regret","thirdPerson":"regrets","past":"regretted","pastParticiple":"regretted","ing":"regretting"},"grammarPatterns":["regret + -ing","regret + that-clause"]}]'::jsonb,'["regrettable","regrettably"]'::jsonb,'[]'::jsonb,'live'),
('vocab_unfamiliar','unfamiliar','adjective','not known or recognised because you have not experienced it before','[{"senseId":"unfamiliar_1","meaning":"not known or recognised because you have not experienced it before","acceptedParaphrases":["not known","new to you"],"masteryContexts":[{"contextId":"u1_14_unfamiliar_meaning","text":"Many of the rules in baseball seemed unfamiliar to the exchange students, because none of them had ever watched a game.","meaning":"not recognised from previous experience","wrongMeanings":["not allowed by the official tournament organisers","too complicated to explain to anyone","already known from earlier lessons"]},{"contextId":"u1_14_unfamiliar_paraphrase","text":"Moving to another country means getting used to unfamiliar food, customs and routines.","meaning":"new or unknown to someone","wrongMeanings":["old-fashioned and rarely seen today","unpleasant and difficult to accept","special to one particular family"]}],"situationDistractors":["Every student in the class knew the rules by heart.","The students played the game they had played for years.","The old pitch was dangerous and nobody wanted to use it.","The new equipment was expensive and heavy.","Everyone in the village knew the old footpath, and they walked along it every morning.","Our students had played that game many times before, so they understood every one of its rules.","Her students recognised every player’s name because they watched matches every weekend.","The goalkeeper trained every evening after school with his older brother for the entire summer."],"gapDistractors":[{"contextId":"u1_14_unfamiliar_gap_meaning_sentence","answer":"unfamiliar","wrong":["familiar","known","recognisable"]},{"contextId":"u1_14_unfamiliar_gap_x1","answer":"unfamiliar","wrong":["affordable","enjoyable","optimistic"]},{"contextId":"u1_14_unfamiliar_gap_x2","answer":"unfamiliar","wrong":["familiar","easy","predictable"]}],"spellingErrors":["unfamilar","unfamiliare","unfimiliar","unfamilliar","unfammiliar","unfamiler"],"wordFamilyForms":[{"form":"unfamiliar","partOfSpeech":"adjective","example":"The new exchange students found the local customs unfamiliar.","pedagogicallyUseful":true},{"form":"familiar","partOfSpeech":"adjective","example":"She soon felt at home because the routines were so familiar.","pedagogicallyUseful":true},{"form":"familiarity","partOfSpeech":"noun","example":"Her familiarity with the course gave her a clear advantage.","pedagogicallyUseful":true},{"form":"familiarise","partOfSpeech":"verb","example":"Take a few minutes to familiarise yourself with the safety rules.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u1_14_unfamiliar_passage_1","contextId":"u1_14_unfamiliar_gap_meaning_sentence","text":"On his first day at the new school, Ravi felt nervous. The corridors, the timetable and even the lunch menu were all completely ____ to him.","answer":"unfamiliar"},{"passageId":"u1_14_unfamiliar_passage_2","contextId":"u1_14_unfamiliar_gap_x1","text":"A first visit to another country can feel strange. Travellers often find the food, language and customs ____, but this is part of the adventure.","answer":"unfamiliar"}],"contextDependentParaphrases":[],"wrongParaphrases":["very famous","well liked","quite common"],"misleadingDistractors":["famous","comfortable","ordinary"]}]'::jsonb,'["familiar","familiarity","familiarise"]'::jsonb,'[]'::jsonb,'live'),
('vocab_racquet','racquet','noun','a sports implement with a handle and strung frame used to hit a ball or shuttlecock','[{"senseId":"racquet_1","meaning":"a sports implement with a handle and strung frame used to hit a ball or shuttlecock","acceptedParaphrases":["bat with strings","strung bat"],"masteryContexts":[{"contextId":"u1_15_racquet_meaning","text":"She replaced the broken strings on her tennis racquet before the final.","meaning":"strung hand-held equipment for hitting","wrongMeanings":["padded protective clothing for sport","hard-wearing footwear for running quickly","light netting that stops a ball"]},{"contextId":"u1_15_racquet_paraphrase","text":"In badminton, players hit the shuttlecock over the net with a light racquet.","meaning":"a light frame with strings and a handle","wrongMeanings":["a solid wooden bat with a very long handle","a heavy stick for striking a puck","a net used to catch a shuttlecock"]}],"situationDistractors":["She tightened the laces on her running shoes before the race.","Her goalkeeper wore thick gloves to protect his hands.","He carried a wooden bat onto the cricket field.","The player hit the ball into the net with her foot.","She lifted the heavy ball with both hands and rolled it down the lane.","Before starting the long mountain climb, the cyclist checked his tyres and fastened his helmet.","She tied her hair back and stretched carefully before the first lap began.","One referee checked the nets before the match started this weekend."],"gapDistractors":[{"contextId":"u1_15_racquet_gap_meaning_sentence","answer":"racquet","wrong":["bat","club","paddle"]},{"contextId":"u1_15_racquet_gap_x1","answer":"racquet","wrong":["club","stick","mallet"]},{"contextId":"u1_15_racquet_gap_x2","answer":"racquet","wrong":["club","mallet","stick"]}],"spellingErrors":["racquit","racqet","raquet","racqeut","racquett","rackquet"],"masteryPassages":[{"passageId":"u1_15_racquet_passage_1","contextId":"u1_15_racquet_gap_meaning_sentence","text":"In the final set, Sara’s ____ slipped from her hand and flew across the court. She had to borrow her partner’s to finish the match.","answer":"racquet"},{"passageId":"u1_15_racquet_passage_2","contextId":"u1_15_racquet_gap_x1","text":"To play badminton you need a shuttlecock, a net and a light ____ with a tightly strung head. A heavier one would make it hard to move quickly.","answer":"racquet"}],"contextDependentParaphrases":[],"wrongParaphrases":["safety hat for the head","whistle used by a referee","net across a court"],"misleadingDistractors":["helmet","whistle","net"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_opponent','opponent','noun','a person or team you compete against','[{"senseId":"opponent_1","meaning":"a person or team you compete against","acceptedParaphrases":["competitor you face","rival"],"masteryContexts":[{"contextId":"u1_16_opponent_meaning","text":"The tennis player shook hands with her opponent, who had just beaten her in three sets.","meaning":"person or team competing against you","wrongMeanings":["person who judges a match fairly","member of the same team as you","person who trains players for matches"]},{"contextId":"u1_16_opponent_paraphrase","text":"Before the game, the captain studied video of the other team’s goalkeeper to find the opponent’s weaknesses.","meaning":"the side you are trying to beat","wrongMeanings":["the group who watch a contest","the people who organise a contest","the last team to enter a contest"]}],"situationDistractors":["The two players trained together every morning as teammates.","A friend watched the whole match from the stands.","The coach shouted instructions from the side of the pitch.","One referee stopped the match to check the score."],"gapDistractors":[{"contextId":"u1_16_opponent_gap_meaning_sentence","answer":"opponent","wrong":["coach","referee","spectator"]},{"contextId":"u1_16_opponent_gap_x1","answer":"opponent","wrong":["trainer","manager","instructor"]},{"contextId":"u1_16_opponent_gap_x2","answer":"opponent","wrong":["spectator","supporter","sponsor"]}],"spellingErrors":["oponent","opponant","oppenent","opponet","opponnent","oppnent"],"wordFamilyForms":[{"form":"opponent","partOfSpeech":"noun","example":"Her opponent made very few mistakes in the final set.","pedagogicallyUseful":true},{"form":"oppose","partOfSpeech":"verb","example":"Several parents oppose the plan to close the sports hall.","pedagogicallyUseful":true,"altExample":"Some parents oppose the plan to shorten the lunch break for training."},{"form":"opposition","partOfSpeech":"noun","example":"There was strong opposition to the new training schedule.","pedagogicallyUseful":true,"altExample":"There was strong opposition to the idea of charging students for the gym."}],"masteryPassages":[{"passageId":"u1_16_opponent_passage_1","contextId":"u1_16_opponent_gap_meaning_sentence","text":"In chess, you must think about every move your ____ might make. A good player always plans two or three moves ahead.","answer":"opponent"},{"passageId":"u1_16_opponent_passage_2","contextId":"u1_16_opponent_gap_x1","text":"The two boxers shook hands and then looked at each other seriously. Neither wanted to show weakness to the ____ before the first bell.","answer":"opponent"}],"contextDependentParaphrases":[],"wrongParaphrases":["member of your team","person who coaches you","judge of the game"],"misleadingDistractors":["coach","spectator","teammate"]}]'::jsonb,'["oppose","opposition"]'::jsonb,'[]'::jsonb,'live'),
('vocab_intense','intense','adjective','very strong, serious, or demanding','[{"senseId":"intense_1","meaning":"very strong, serious, or demanding","acceptedParaphrases":["very demanding","extremely strong"],"masteryContexts":[{"contextId":"u1_17_intense_meaning","text":"Players faced intense pressure in the final minutes, with the score level and the whole crowd roaring.","meaning":"extreme in strength or effort","wrongMeanings":["mild and easy to manage","calm and slow to develop","limited to a short period each day"]},{"contextId":"u1_17_intense_paraphrase","text":"The sun was so intense that the runners had to stop for water every few minutes.","meaning":"very strong and hard to bear","wrongMeanings":["gentle and pleasant to feel","difficult to see clearly","changing quickly from hour to hour"]}],"situationDistractors":["The training session was short and very relaxed.","The match was cancelled because of heavy rain.","The crowd was small and quiet throughout the final.","The race lasted a long time but was easy for the runners."],"gapDistractors":[{"contextId":"u1_17_intense_gap_meaning_sentence","answer":"intense","wrong":["financial","medical","annual"]},{"contextId":"u1_17_intense_gap_x1","answer":"intense","wrong":["mild","gentle","pleasant"]},{"contextId":"u1_17_intense_gap_x3","answer":"intense","wrong":["weak","casual","occasional"]}],"spellingErrors":["intence","intens","intese","intesne","intsense","entense"],"wordFamilyForms":[{"form":"intense","partOfSpeech":"adjective","example":"The heat during the final lap was intense.","pedagogicallyUseful":true},{"form":"intensity","partOfSpeech":"noun","example":"The intensity of the training session surprised the beginners.","pedagogicallyUseful":true},{"form":"intensely","partOfSpeech":"adverb","example":"She trained intensely for six weeks before the national trials.","pedagogicallyUseful":true},{"form":"intensify","partOfSpeech":"verb","example":"Runners usually intensify their training as a race approaches.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u1_17_intense_passage_1","contextId":"u1_17_intense_gap_meaning_sentence","text":"The final minutes of the match were ____. Both teams attacked again and again, and no one in the stadium dared to sit down.","answer":"intense"},{"passageId":"u1_17_intense_passage_2","contextId":"u1_17_intense_gap_x1","text":"Summer in the desert is ____. The sun burns the skin within minutes, and walkers need shade and plenty of water.","answer":"intense"}],"contextDependentParaphrases":[],"wrongParaphrases":["quite relaxed","fairly short","rather casual"],"misleadingDistractors":["gentle","ordinary","brief"]}]'::jsonb,'["intensity","intensely","intensify"]'::jsonb,'["intense competition","intense training"]'::jsonb,'live'),
('vocab_tournament','tournament','noun','a competition involving several players or teams over a series of matches','[{"senseId":"tournament_1","meaning":"a competition involving several players or teams over a series of matches","acceptedParaphrases":["competition","series of matches"],"masteryContexts":[{"contextId":"u1_18_tournament_meaning","text":"Sixteen schools entered the knockout tournament, and only the winners of each match went through to the next round.","meaning":"organised competition with several matches","wrongMeanings":["single match between two famous teams","training programme for young players","ceremony for presenting prizes to the winners"]},{"contextId":"u1_18_tournament_paraphrase","text":"He scored the winning goal in the semi-final of the tournament, which his team went on to win.","meaning":"multi-match event that determines a winner","wrongMeanings":["final game played at season’s end","meeting held to choose the best young players","series of lessons given by a coach"]}],"situationDistractors":["Two friends played a single game of tennis in the park.","The team practised passing for an hour after lessons.","A coach gave a talk to parents about healthy eating.","Fans travelled by train to watch a friendly match.","Every morning, the whole school gathers in the main hall for assembly.","Both teams practised their passing drills for an hour before stopping for a long lunch.","Two neighbouring schools arranged a friendly basketball match for the following afternoon.","Tourists photographed the cathedral, then bought postcards from the market stalls.","The librarian recommended interesting biographies to curious teenagers."],"gapDistractors":[{"contextId":"u1_18_tournament_gap_meaning_sentence","answer":"tournament","wrong":["lesson","library","celebration"]},{"contextId":"u1_18_tournament_gap_x1","answer":"tournament","wrong":["racquet","court","celebration"]},{"contextId":"u1_18_tournament_gap_x2","answer":"tournament","wrong":["lesson","library","celebration"]}],"spellingErrors":["tornament","tournement","tourment","tournamnet","toornament","tournamant"],"masteryPassages":[{"passageId":"u1_18_tournament_passage_1","contextId":"u1_18_tournament_gap_meaning_sentence","text":"Sixty-four teams entered the ____, which lasted a whole week. Each team played once a day until only two remained for the final.","answer":"tournament"},{"passageId":"u1_18_tournament_passage_2","contextId":"u1_18_tournament_gap_x1","text":"Omar said this was only a friendly match. The real excitement comes next month, when we travel to the national ____ and play against the best schools.","answer":"tournament"}],"contextDependentParaphrases":[],"wrongParaphrases":["workshop","exhibition","celebration"],"misleadingDistractors":["training session","team meeting","sports lesson"]}]'::jsonb,'[]'::jsonb,'["enter a tournament","tournament final"]'::jsonb,'live'),
('vocab_determined','determined','adjective','firmly decided to achieve something and unwilling to give up','[{"senseId":"determined_1","meaning":"firmly decided to achieve something and unwilling to give up","acceptedParaphrases":["strongly motivated","resolved"],"masteryContexts":[{"contextId":"u1_19_determined_meaning","text":"Even after three defeats, she was determined to qualify for the national team and refused to give up.","meaning":"firmly committed to achieving an aim","wrongMeanings":["secretly worried about failing to win","fully satisfied with an earlier result","unsure about joining a national team"]},{"contextId":"u1_19_determined_paraphrase","text":"The team was determined to win the match despite being two goals behind at half-time.","meaning":"unwilling to give up on a goal","wrongMeanings":["certain that the match would end soon","unable to continue because of tiredness","prepared to accept a heavy defeat"]}],"situationDistractors":["He gave up after the first kilometre because he felt tired.","She was not sure whether she wanted to run at all.","The runner was forced to stop by an injury.","He did not care whether he finished the race or not.","After losing the first set, he gave up and walked silently off the court.","Feeling unsure about the race, she nearly stayed at home that morning.","Frustrated by the heavy defeat, she considered giving up the sport completely.","Nobody expected the substitute to score, but everybody applauded him politely.","The referee checked the equipment bags before the visiting team arrived."],"gapDistractors":[{"contextId":"u1_19_determined_gap_meaning_sentence","answer":"determined","wrong":["reluctant","afraid","embarrassed"]},{"contextId":"u1_19_determined_gap_x1","answer":"determined","wrong":["reluctant","afraid","embarrassed"]},{"contextId":"u1_19_determined_gap_x2","answer":"determined","wrong":["lazy","careless","discouraged"]}],"spellingErrors":["determind","determaned","detirmined","determinned","determiend","detirmend"],"wordFamilyForms":[{"form":"determined","partOfSpeech":"adjective","example":"Even after a heavy defeat, the team stayed determined to improve.","pedagogicallyUseful":true},{"form":"determine","partOfSpeech":"verb","example":"The final score will determine which team wins the league.","pedagogicallyUseful":true,"altExample":"Judges determine the winner by adding up the points from every round."},{"form":"determination","partOfSpeech":"noun","example":"Her determination to succeed impressed every coach.","pedagogicallyUseful":true,"altExample":"Her determination to improve her time impressed everybody at the club."}],"masteryPassages":[{"passageId":"u1_19_determined_passage_1","contextId":"u1_19_determined_gap_meaning_sentence","text":"Mia had failed her driving test twice, but she was ____ to pass the third time. She practised every evening for a month.","answer":"determined"},{"passageId":"u1_19_determined_passage_2","contextId":"u1_19_determined_gap_x1","text":"The climbers were exhausted and the storm was growing worse. Yet they remained ____ to reach the summit before dark.","answer":"determined"}],"contextDependentParaphrases":[],"wrongParaphrases":["easily discouraged","rather uncertain","quite careless"],"misleadingDistractors":["uncertain","careless","relaxed"]}]'::jsonb,'["determine","determination"]'::jsonb,'["determined to succeed"]'::jsonb,'live'),
('vocab_discipline','discipline','noun','the self-control needed to follow rules or work consistently toward a goal','[{"senseId":"discipline_1","meaning":"the self-control needed to follow rules or work consistently toward a goal","acceptedParaphrases":["self-control","consistent control"],"masteryContexts":[{"contextId":"u1_20_discipline_meaning","text":"Training at five every morning in winter takes real discipline, because nobody forces you to keep to the routine.","meaning":"self-control that supports steady daily effort","wrongMeanings":["natural talent seen from a very early age","strong dislike of early morning exercise","pleasure gained from winning difficult races"]},{"contextId":"u1_20_discipline_paraphrase","text":"Success in a sport depends on talent, but it also depends on the discipline to follow a strict timetable even when you feel tired.","meaning":"controlled behaviour for following a plan","wrongMeanings":["punishment given for breaking a school rule","knowledge gained after many years abroad","energy needed for a very long race"]}],"situationDistractors":["Their team was lucky to win the final goal in extra time.","She has a natural talent for running fast.","The players were punished for being late to the bus.","He trains hard only when someone is watching him.","The squad spent the whole evening watching videos of old matches together.","He was lucky to be selected, because the other player had badly injured his knee in training.","Her goalkeeper’s natural talent was obvious from his very first training session.","Coaches rescheduled the gala because transport was cancelled suddenly."],"gapDistractors":[{"contextId":"u1_20_discipline_gap_meaning_sentence","answer":"discipline","wrong":["laziness","forgiveness","nervousness"]},{"contextId":"u1_20_discipline_gap_x1","answer":"discipline","wrong":["flexibility","laziness","generosity"]},{"contextId":"u1_20_discipline_gap_x2","answer":"discipline","wrong":["panic","laziness","nervousness"]}],"spellingErrors":["disipline","discipine","dicipline","discapline","disciplin","discipleine"],"wordFamilyForms":[{"form":"discipline","partOfSpeech":"noun","example":"A strong sense of discipline helps athletes train even on cold mornings.","pedagogicallyUseful":true},{"form":"disciplined","partOfSpeech":"adjective","example":"The disciplined squad arrived early and warmed up quietly.","pedagogicallyUseful":true,"altExample":"A disciplined athlete goes to bed early before a big race."},{"form":"undisciplined","partOfSpeech":"adjective","example":"The coach criticised the team for its undisciplined play in the second half.","pedagogicallyUseful":true,"altExample":"The undisciplined team kept arguing instead of following the plan."}],"masteryPassages":[{"passageId":"u1_20_discipline_passage_1","contextId":"u1_20_discipline_gap_meaning_sentence","text":"Getting up at five every day to swim needs a great deal of ____. Talent alone is not enough if you cannot make yourself train when you are tired.","answer":"discipline"},{"passageId":"u1_20_discipline_passage_2","contextId":"u1_20_discipline_gap_x1","text":"Dieting is easy to start but hard to continue. It takes real ____ to turn down cake every day for months.","answer":"discipline"}],"contextDependentParaphrases":[],"wrongParaphrases":["luck","talent","entertainment"],"misleadingDistractors":["luck","talent","entertainment"],"teacherNote":"Use the self-control/training sense here, not punishment or a school subject."}]'::jsonb,'["disciplined","undisciplined"]'::jsonb,'["self-discipline","training discipline"]'::jsonb,'live')
